from fractions import Fraction


def best_average(a: list[int], k: int) -> list[int]:
    n = len(a)
    prefix = [0] * (n + 1)
    for i, value in enumerate(a):
        prefix[i + 1] = prefix[i] + value

    # Maintain candidate starting prefixes on the lower convex hull.
    hull = []
    head = 0
    best_num = 0
    best_den = 1

    for end in range(k, n + 1):
        start = end - k

        while len(hull) - head >= 2:
            x, y = hull[-2], hull[-1]
            if (prefix[y] - prefix[x]) * (start - y) >= (
                prefix[start] - prefix[y]
            ) * (y - x):
                hull.pop()
            else:
                break
        hull.append(start)

        while len(hull) - head >= 2:
            x, y = hull[head], hull[head + 1]
            if (prefix[end] - prefix[x]) * (end - y) <= (
                prefix[end] - prefix[y]
            ) * (end - x):
                head += 1
            else:
                break

        start = hull[head]
        num = prefix[end] - prefix[start]
        den = end - start
        if num * best_den > best_num * den:
            best_num, best_den = num, den

        if head > 1024 and head * 2 > len(hull):
            hull = hull[head:]
            head = 0

    divisor = __import__("math").gcd(best_num, best_den)
    return [best_num // divisor, best_den // divisor]
